def word_count_difference(text1, text2):
    counts1 = {}
    for w in text1.split():
        counts1[w] = counts1.get(w, 0) + 1
    counts2 = {}
    for w in text2.split():
        counts2[w] = counts2.get(w, 0) + 1
    all_words = set(counts1) | set(counts2)
    diff = {}
    for w in all_words:
        diff[w] = counts1.get(w, 0) - counts2.get(w, 0)
    return diff

def group_consecutive_same_case(s):
    letters = [c for c in s if c.isalpha()]
    groups = []
    for c in letters:
        if groups and groups[-1][-1].isupper() == c.isupper():
            groups[-1] += c
        else:
            groups.append(c)
    return groups

