def sentence_case_keep_i(s):
    lowered = s.lower()
    parts = lowered.split(" ")
    fixed = []
    for w in parts:
        fixed.append("I" if w == "i" else w)
    result = " ".join(fixed)
    for idx in range(len(result)):
        if result[idx].isalpha():
            return result[:idx] + result[idx].upper() + result[idx + 1:]
    return result

def median_index(nums):
    s = sorted(nums)
    n = len(s)
    mid = n // 2 if n % 2 == 1 else n // 2 - 1
    target = s[mid]
    for i, v in enumerate(nums):
        if v == target:
            return i
    return -1

def is_valid_range_string(s):
    segments = s.split('-')
    if len(segments) != 2:
        return False
    left, right = segments
    for part in (left, right):
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
    return int(left) <= int(right)

