def is_valid_json_number(s):
    i = 0
    n = len(s)
    if i < n and s[i] == '-':
        i += 1
    start = i
    if i < n and s[i] == '0':
        i += 1
    elif i < n and s[i].isdigit() and s[i] != '0':
        i += 1
        while i < n and s[i].isdigit():
            i += 1
    else:
        return False
    if i < n and s[i] == '.':
        i += 1
        frac_start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == frac_start:
            return False
    if i < n and s[i] in 'eE':
        i += 1
        if i < n and s[i] in '+-':
            i += 1
        exp_start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == exp_start:
            return False
    return i == n and start < i

