def longest_sorted_run_length(arr):
    if not arr:
        return 0
    best = current = 1
    for i in range(1, len(arr)):
        if arr[i] >= arr[i - 1]:
            current += 1
        else:
            current = 1
        best = max(best, current)
    return best

def least_common_element(seq):
    if len(seq) == 0:
        return None
    counts = {}
    for x in seq:
        counts[x] = counts.get(x, 0) + 1
    candidates = sorted(counts.keys(), key=lambda k: (counts[k], k))
    return candidates[0]

